+		printCheckpointRemoteHint(target)
+		return nil
+	}
+	stop(" done")
+
+	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", label, displayTarget)
+	stop = startProgressDots(os.Stderr)
