+	if result, err := tryPushMappedRef(ctx, target, localRef, remoteRef); err != nil {
+		stop("")
+		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", label, err)
+		printCheckpointRemoteHint(target)
